import mockProject from '../../../tests/fixtures/project.mock.json';
import type { Project, ViewerProject } from '../types';

/**
 * Published projects for the public Viewer.
 *
 * STUB (WS-E): until the Supabase `projects` table and public view exist, the
 * mock project generated by `pnpm mock` is the only published exhibit. Its
 * asset paths resolve against `/` (files in public/fixtures/).
 */
const FIXTURES: Record<string, Project> = {
  [mockProject.id]: mockProject as unknown as Project,
};

export async function getPublishedProject(id: string): Promise<ViewerProject | null> {
  const p = FIXTURES[id];
  if (!p || p.status !== 'published') return null;
  const { title, description, model, objectToMat, calibration, mat, annotations } = p;
  return { id: p.id, title, description, model, objectToMat, calibration, mat, annotations };
}

/** Base URL that project storage paths (glbPath, imagePath, …) are relative to. */
export function assetBaseUrl(): string {
  return '/';
}
